function suggest(group,profile){return [...group.courses].sort((a,b)=>{const rank=x=>profile.priority.includes(x)?profile.priority.indexOf(x):1000+group.courses.indexOf(x);return rank(a)-rank(b)}).slice(0,group.count)}
function matchCareer(text){const q=text.toLowerCase().replace(/\s/g,'');return curriculum.profiles.filter(p=>p.keywords.some(k=>q.includes(k)))}
if(typeof module!=='undefined')module.exports={curriculum,suggest,matchCareer};
